#include "opeu/platform/build-identity.hpp"

// Generated by buildutil on every configure; included here and nowhere
// else, so the moving build time recompiles this one file.
#include "opeurptv/buildinfo.hpp"

#include <format>

namespace opeu::platform::detail::build_identity {

namespace {

constexpr auto THIS_BUILD{ BuildIdentity{
  .version = OPEURPTV_BUILD_VERSION,
  .commit  = OPEURPTV_BUILD_COMMIT,
  .tag     = OPEURPTV_BUILD_TAG,
  .time    = OPEURPTV_BUILD_TIME,
  .dirty   = OPEURPTV_BUILD_DIRTY != 0,
  .number  = OPEURPTV_BUILD_NUMBER,
} };

}

auto ThisBuild() noexcept -> BuildIdentity const& {
  return THIS_BUILD;
}

auto Describe(BuildIdentity const& build) -> std::string {
  if (build.time.empty()) {
    return std::format("opeurptv {} (build {})", build.version, build.number);
  }
  return std::format("opeurptv {} (build {}, {})", build.version, build.number,
                     build.time);
}

}
